WORD_KEYS = ["summary", "definition", "main_problem", "mechanism", "critiques",
             "applications", "evolution", "key_concepts", "principles", "studies",
             "assumptions"]


def main():
    spec = importlib.util.spec_from_file_location("fw", "scripts/kb_batch238_framework.py")
    fw = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(fw)
    conn = pymysql.connect(host="127.0.0.1", port=3306, user="root", password="433700",
                           database=DB, charset="utf8mb4", autocommit=False)
    cur = conn.cursor()
    codes = list(PARAS.keys())
    ph = ",".join(["%s"] * len(codes))
    cur.execute("SELECT id,code,properties FROM kb_entities WHERE code IN (%s)" % ph, codes)
    rows = cur.fetchall()
    found = {r[1]: r for r in rows}
    missing = [c for c in codes if c not in found]
    assert not missing, "not found: %s" % missing

    snap = [{"id": r[0], "code": r[1], "properties": json.loads(r[2])} for r in rows]
    with open(BACKUP, "w", encoding="utf-8") as f:
        json.dump(snap, f, ensure_ascii=False, indent=1)
    print("backup ->", len(snap), "rows")

    ok = 0
    for i, code in enumerate(codes, 1):
        eid, _c, props = found[code]
        p = json.loads(props)
        f_ = FIELD[code]
        p[f_] = (p.get(f_) or "") + PARAS[code]

        cur.execute("SELECT COUNT(*) FROM kb_relations WHERE source_id=%s OR target_id=%s", (eid, eid))
        n_rel = cur.fetchone()[0]
        n_sources = len(p.get("sources") or [])
        n_verified = sum(1 for x in (p.get("citations") or []) if x.get("verified"))
        score, detail, words = fw.rubric(p, n_verified, n_sources, n_rel)

        # hard requirements: words >= 500, score >= 96 ; target words >= 515
        status = "OK"
        if words < 500 or score < 96:
            status = "FAIL(hard)"
        elif words < 515:
            status = "OK(under515)"
        if status == "FAIL(hard)":
            print("!! REFUSE %s: words=%d score=%d (need >=500 words & >=96)" % (code, words, score))
            continue

        p["quality_score"] = score
        p["quality_assessment"] = "ارزیابی خودکار SPEC §6.1: %d/100 (نمره پایه؛ نیازمند بازبینی علمی انسانی)" % score
        p["status_scientific_note"] = "مستندسازی با منابع تأییدشده شبکه‌ای؛ نمره بر پایه سنجه خودکار است و جانشین داوری علمی (SPEC §6.4) نیست."
        p["updated_at"] = NOW
        p["updated_by"] = STAMP

        cur.execute("UPDATE kb_entities SET properties=%s, version=version+1, updated_at=%s WHERE id=%s",
                    (json.dumps(p, ensure_ascii=False), NOW, eid))
        cur.execute("SELECT version FROM kb_entities WHERE id=%s", (eid,))
        new_version = cur.fetchone()[0]
        cur.execute("""INSERT INTO kb_entity_versions
            (entity_id,version,snapshot,change_reason,changed_by,created_at)
            VALUES (%s,%s,%s,%s,%s,%s)""",
                    (eid, new_version, json.dumps(p, ensure_ascii=False),
                     "pad word count to rubric>=96 (append scholarly paragraph to %s)" % f_, STAMP, NOW))
        cur.execute("""INSERT INTO kb_audit_log (entity_code,action,detail,source,created_at)
            VALUES (%s,'DOC_PAD',%s,%s,%s)""",
                    (code, json.dumps({"batch": 366, "field": f_, "score": score,
                                       "words": words, "sources": n_sources,
                                       "verified": n_verified, "relations": n_rel,
                                       "rubric": detail}, ensure_ascii=False), STAMP, NOW))
        print("%s -> %s: words=%d score=%d nrel=%d nsrc=%d nver=%d | %s"
              % (code, f_, words, score, n_rel, n_sources, n_verified, status))
        ok += 1
        if i % 5 == 0:
            conn.commit()
            print("---- committed through %s (%d/%d)" % (code, i, len(codes)))

    conn.commit()
    conn.close()
    print("PADB DONE: %d updated" % ok)


if __name__ == "__main__":
    main()
